import { Router } from "express";
import type { PrismaClient } from "@prisma/client";
import { OrderController } from "./order.controller.js";
import { OrderRepository } from "./order.repository.js";
import { OrderService } from "./order.service.js";
import { validate } from "../middlewares/validate.js";
import { createOrderSchema } from "./order.schema.js";

export function createOrderRouter(prisma: PrismaClient): Router {
  const repository = new OrderRepository(prisma);
  const service = new OrderService(prisma, repository);
  const controller = new OrderController(service);
  const router = Router();

  router.post("/orders", validate(createOrderSchema), controller.create);
  return router;
}
